var n=`0515-tashreeb`;var i=`world-0515`;var a=`IQ`;var r=`western-asia`;var o=4;var s=106;var l={en:`Tashreeb`,ua:`Ташріб`};var g={en:`A traditional dish from Iraq, centered on lamb, yellow onion, carrot, tomato. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Ірак. Основні складники: ягнятина, жовта цибуля, морква, помідор. Домашній варіант із кількостями продуктів за етапами приготування.`};var d=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 13 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 13 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:13,i:[[`lamb`,680,`g`],[`yellow-onion`,180,`g`],[`unsalted-butter`,50,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 85 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 85 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:85,i:[[`chicken-stock`,1200,`ml`],[`carrot`,160,`g`],[`tomato`,230,`g`],[`allspice-berries`,5,`g`]]},{en:`Assemble the cooled components with the listed fillings or toppings. Refrigerate briefly if needed to set the layers.`,ua:`Зберіть охолоджені частини з зазначеними начинками або покриттям. За потреби ненадовго охолодіть для стабілізації шарів.`,t:[`layered-assembly`,`garnishing`],m:8,i:[[`pita-bread`,4,`pcs`],[`parsley`,20,`g`]]}];var m={slug:n,id:i,country:`IQ`,region:r,servings:4,minutes:106,title:l,text:g,steps:d};export{a as country,m as default,i as id,s as minutes,r as region,o as servings,n as slug,d as steps,g as text,l as title};